mapper.select:
SELECT d.id AS id_device, d.datatablename AS data_table_name FROM device d WHERE d.meter_type = 14 AND d.`status` = 1 AND d.is_delete = 0
AND d.id_site IN
#{site}

mapper.sql:
FROM
	bems_tenant_billing_daily_summary
WHERE
	id_site = #{id_site}
	AND id_device = #{id_device}
	AND id_device IN (SELECT id FROM device WHERE is_delete = 0)
	AND `date` BETWEEN #{start_date} AND #{end_date}

mapper.select:
SELECT t.serial, t.tenant_name, t.location, t.multiplier, o.opening_reading, o.`date` AS opening_time, c.closing_reading, CONCAT(c.`date`, ' ', LEFT(c.last_time, 5)) AS closing_time, ROUND((c.closing_reading - o.opening_reading) * t.multiplier, 2) AS kwh, t.status FROM (
WHERE 1 = 1
AND id_location = #{id_location}
) t LEFT JOIN bems_tenant_billing_daily_summary o ON o.id = ( SELECT s.id FROM bems_tenant_billing_daily_summary s WHERE s.id_device = t.id_device AND s.id_site = #{id_site} AND s.`date` BETWEEN #{start_date} AND #{end_date} ORDER BY s.`date` ASC LIMIT 1 ) LEFT JOIN bems_tenant_billing_daily_summary c ON c.id = ( SELECT s.id FROM bems_tenant_billing_daily_summary s WHERE s.id_device = t.id_device AND s.id_site = #{id_site} AND s.`date` BETWEEN #{start_date} AND #{end_date} ORDER BY s.`date` DESC LIMIT 1 ) ORDER BY t.status = 'incomplete', CAST(t.serial AS UNSIGNED)
